const INITIAL_TOKENS = [
  { id: 1, text: "⚡ MeshTalk Native", color: "#10b981", bg: "rgba(16, 185, 129, 0.15)", border: "rgba(16, 185, 129, 0.4)", x: 120, y: 100, vx: 1.2, vy: -0.8, r: 60, angle: 0, va: 0.02 },
