// 2. Zedox Rarity RNG Simulator
const RngSimulator = () => {
  const [rollResult, setRollResult] = useState({ name: 'Standard Particle', tier: 'COMMON', rate: '75%', color: '#94a3b8' });
  const [isRolling, setIsRolling] = useState(false);
  const [totalRolls, setTotalRolls] = useState(1);

  const rollTiers = [
    { name: 'Cosmic Singularity (1 in 50,000)', tier: 'MYTHIC', rate: '0.002%', color: '#ec4899' },
    { name: 'Quantum Core (1 in 2,500)', tier: 'LEGENDARY', rate: '0.04%', color: '#f59e0b' },
    { name: 'Hyper-Dense Plasma (1 in 250)', tier: 'EPIC', rate: '0.4%', color: '#a855f7' },
    { name: 'Charged Filament', tier: 'RARE', rate: '8.0%', color: '#00f0ff' },
    { name: 'Standard Particle', tier: 'COMMON', rate: '91.5%', color: '#94a3b8' }
  ];

  const handleRoll = () => {
    if (isRolling) return;
    setIsRolling(true);
    sound.playClick(600, 0.04);

    let counter = 0;
    const interval = setInterval(() => {
      const randomIdx = Math.floor(Math.random() * rollTiers.length);
      setRollResult(rollTiers[randomIdx]);
      sound.playKeyBeep();
      counter++;

      if (counter > 8) {
        clearInterval(interval);
        // Determine final weighted roll
        const rand = Math.random();
        let final;
        if (rand < 0.05) {
          final = rollTiers[0]; // Mythic!
          sound.playJackpot();
          try {
            confetti({ particleCount: 60, spread: 70, origin: { y: 0.7 } });
          } catch(e){}
        } else if (rand < 0.20) {
          final = rollTiers[1]; // Legendary
          sound.playPowerUp();
        } else if (rand < 0.45) {
          final = rollTiers[2];
          sound.playHover(900, 0.06);
        } else if (rand < 0.75) {
          final = rollTiers[3];
          sound.playHover(700, 0.05);
        } else {
          final = rollTiers[4];
          sound.playClick(800, 0.04);
        }

        setRollResult(final);
        setTotalRolls(prev => prev + 1);
        setIsRolling(false);
      }
    }, 60);
  };

  return (
    <div className="sim-screen" style={{ marginTop: '1rem', borderColor: 'rgba(245, 158, 11, 0.3)' }}>
      <div className="flex justify-between items-center" style={{ marginBottom: '0.5rem' }}>
        <span style={{ fontSize: '0.75rem', color: '#f59e0b', fontWeight: 'bold' }}>
          LIVE DETERMINISTIC RNG CORE
        </span>
        <span className="glass-pill" style={{ fontSize: '0.65rem' }}>
          SEED: 0x{Math.floor(Math.random() * 0xFFFFFF).toString(16).toUpperCase()}
        </span>
      </div>

      <div
        style={{
          padding: '0.75rem',
          background: 'rgba(0,0,0,0.5)',
          borderRadius: '8px',
          textAlign: 'center',
          border: `1px solid ${rollResult.color}50`
        }}
      >
        <div style={{ fontSize: '0.7rem', color: rollResult.color, fontWeight: 'bold', letterSpacing: '1px' }}>
          [ {rollResult.tier} // ODDS: {rollResult.rate} ]
        </div>
        <div style={{ fontSize: '1rem', fontWeight: 'bold', color: '#ffffff', marginTop: '0.25rem' }}>
          {rollResult.name}
        </div>
      </div>

      <button
        onClick={handleRoll}
        disabled={isRolling}
        className="btn btn-sm btn-primary"
        style={{ width: '100%', marginTop: '0.75rem', fontSize: '0.75rem', background: 'linear-gradient(135deg, #f59e0b, #d97706)', color: '#000000' }}
      >
        <Dices size={14} />
        {isRolling ? 'CALCULATING ENTROPY SEED...' : `EXECUTE SEED ROLL (#${totalRolls})`}
      </button>
    </div>
  );
};

