import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Terminal as TerminalIcon, CornerDownLeft, Sparkles, RefreshCw } from 'lucide-react';
import { PORTFOLIO_DATA } from '../data/portfolioData';
import { sound } from '../utils/audioEngine';

const InteractiveTerminal = ({ onOpenShowreel, onToggleZeroG, onToggleScanlines }) => {
  const [input, setInput] = useState('');
  const [history, setHistory] = useState([
    { type: 'system', text: 'ANTIGRAVITY OS v2.6.4 (x86_64-zedox-sys)' },
    { type: 'system', text: 'Type "help" to display available protocols and subroutines.' }
  ]);
  const [cmdHistory, setCmdHistory] = useState([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [history]);

  const handleCommand = (cmdStr) => {
    const cleanCmd = cmdStr.trim().toLowerCase();
    if (!cleanCmd) return;

    sound.playClick(950, 0.04);
    setCmdHistory(prev => [cmdStr, ...prev]);
    setHistoryIndex(-1);

    const newHistory = [...history, { type: 'user', text: `$ ${cmdStr}` }];

    switch (cleanCmd) {
      case 'help':
        newHistory.push({
          type: 'output',
          text: PORTFOLIO_DATA.terminalHelp
            .map(h => `  • ${h.cmd.padEnd(12, ' ')} : ${h.desc}`)
            .join('\n')
        });
        break;

      case 'whoami':
        newHistory.push({
          type: 'output',
          text: `HANDLE: ${PORTFOLIO_DATA.profile.handle}\nROLE  : ${PORTFOLIO_DATA.profile.tagline}\nSTATUS: ${PORTFOLIO_DATA.profile.status}\nLOC   : ${PORTFOLIO_DATA.profile.location}`
        });
        break;

      case 'projects':
        newHistory.push({
          type: 'output',
          text: PORTFOLIO_DATA.projects
            .map(p => `  [+] ${p.title} (${p.category})\n      ${p.tagline}`)
            .join('\n')
        });
        break;

      case 'showreel':
        newHistory.push({ type: 'success', text: '>> Launching Antigravity Keynote Showreel Player...' });
        sound.playPowerUp();
        setTimeout(() => onOpenShowreel(), 400);
        break;

      case 'zerog':
        newHistory.push({ type: 'success', text: '>> Toggling Gravitational Field to Zero-G...' });
        sound.playWhoosh();
        onToggleZeroG();
        break;

      case 'matrix':
        newHistory.push({ type: 'success', text: '>> Toggling CRT Scanlines Mode...' });
        sound.playLaser();
        onToggleScanlines();
        break;

      case 'skills':
        newHistory.push({
          type: 'output',
          text: PORTFOLIO_DATA.skills
            .map(s => `  [${s.category}]\n  ${s.items.map(i => `  - ${i.name} [${i.level}%]`).join('\n')}`)
            .join('\n\n')
        });
        break;

      case 'roll':
        sound.playKeyBeep();
        const rand = Math.random();
        let item = rand < 0.05 ? '⭐ MYTHIC: Cosmic Singularity (1 in 50k)' : rand < 0.25 ? '✨ LEGENDARY: Quantum Core' : '⚡ COMMON: Standard Shard';
        newHistory.push({ type: 'output', text: `>> RNG OUTPUT: ${item}` });
        break;

      case 'ping':
        sound.playKeyBeep();
        newHistory.push({
          type: 'output',
          text: `Pinging edge cluster zedox-ams-01.infra [194.38.20.1]...\n64 bytes from zedox-ams: icmp_seq=1 ttl=58 time=11.4 ms\n64 bytes from zedox-ams: icmp_seq=2 ttl=58 time=10.9 ms\n--- 0.0% packet loss, RTT avg = 11.1ms ---`
        });
        break;

      case 'contact':
        newHistory.push({
          type: 'output',
          text: `DISCORD : ${PORTFOLIO_DATA.profile.discordTag}\nGITHUB  : ${PORTFOLIO_DATA.profile.githubUrl}\nEMAIL   : ${PORTFOLIO_DATA.profile.email}`
        });
        break;

      case 'clear':
        setHistory([]);
        setInput('');
        return;

      default:
        sound.playError();
        newHistory.push({
          type: 'error',
          text: `Command not recognized: "${cmdStr}". Type "help" for a list of available subroutines.`
        });
        break;
    }

    setHistory(newHistory);
    setInput('');
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleCommand(input);
    } else if (e.key === 'ArrowUp') {
      if (cmdHistory.length > 0 && historyIndex < cmdHistory.length - 1) {
        const nextIdx = historyIndex + 1;
        setHistoryIndex(nextIdx);
        setInput(cmdHistory[nextIdx]);
      }
    } else if (e.key === 'ArrowDown') {
      if (historyIndex > 0) {
        const nextIdx = historyIndex - 1;
        setHistoryIndex(nextIdx);
        setInput(cmdHistory[nextIdx]);
      } else {
        setHistoryIndex(-1);
        setInput('');
      }
    } else {
      sound.playKeyBeep();
    }
  };

  return (
    <section className="container section-spacing" id="terminal">
      <div className="flex flex-col flex-md-row justify-between items-start items-md-center gap-4" style={{ marginBottom: '2.5rem' }}>
        <div>
          <div className="flex items-center gap-2" style={{ marginBottom: '0.5rem' }}>
            <span className="telemetry-dot" style={{ backgroundColor: 'var(--accent-cyan)' }} />
            <span style={{ color: 'var(--accent-cyan)', fontWeight: 'bold', fontSize: '0.8rem', letterSpacing: '2px', textTransform: 'uppercase' }}>
              Command Shell & Telemetry
            </span>
          </div>
          <h2 style={{ fontSize: 'clamp(2rem, 5vw, 3rem)' }}>
            ANTIGRAVITY <span className="text-gradient">CLI TERMINAL</span>
          </h2>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.95rem', maxWidth: '520px', marginTop: '0.5rem' }}>
            Direct shell interface to explore system specs, launch showreel keynote decks, test server pings, or trigger zero-g physics.
          </p>
        </div>

        {/* Quick Command Chips */}
        <div className="flex flex-wrap gap-2">
          {['help', 'showreel', 'projects', 'zerog', 'ping'].map(cmd => (
            <button
              key={cmd}
              onClick={() => handleCommand(cmd)}
              className="btn btn-sm btn-outline"
              style={{ fontFamily: 'var(--font-mono)', fontSize: '0.75rem', borderColor: 'rgba(0, 240, 255, 0.25)' }}
            >
              $ {cmd}
            </button>
          ))}
        </div>
      </div>

      {/* Terminal Window Box */}
      <div
        className="glass-panel"
        style={{
